/**
 * Generate the manifest `@lyteboat/distro` publishes at runtime from the
 * registry: `dsh-compat/contract/extensions.yml` (the extensions this build carries) and
 * `dsh.upstream.json` (the release the kernel was imported from). The runtime
 * plugin cannot read either file from an installed build, so the facts are
 * compiled in. `--check` fails when the committed module is stale; `pnpm run
 * lint` runs it.
 *
 *   node --import tsx scripts/dist/gen-distro-manifest.ts [--check]
 * @module scripts/dist/gen-distro-manifest
 */

import { readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { readExtensions } from './contract-check.ts'
import { readUpstreamPin, repoRoot } from './kernel.ts'

const TARGET = join(repoRoot, 'lyteboat/plugins/distro/src/distro-manifest.ts')

/** A single-quoted TypeScript string literal. */
function quote(text: string): string {
  return `'${text.replaceAll('\\', '\\\\').replaceAll("'", "\\'")}'`
}

export function renderDistroManifest(): string {
  const extensions = readExtensions().map(({ id, package: pkg, kind, since }) =>
    `  { id: ${quote(id)}, package: ${quote(pkg)}, kind: ${quote(kind)}, since: ${quote(since)} },`)
  return [
    '// Generated by scripts/dist/gen-distro-manifest.ts from dsh-compat/contract/extensions.yml and',
    '// dsh.upstream.json. Do not edit; rerun the script after changing either file.',
    "import type { LyteboatDistroExtension } from '@lyteboat/contracts'",
    '',
    '/** The dsh release the kernel was imported from. */',
    `export const DSH_BASE = ${quote(readUpstreamPin().dsh)}`,
    '',
    '/** Every kernel extension this build carries. */',
    'export const DISTRO_EXTENSIONS: readonly LyteboatDistroExtension[] = Object.freeze([',
    ...extensions,
    '])',
    '',
  ].join('\n')
}

const expected = renderDistroManifest()
if (process.argv.includes('--check')) {
  let actual = ''
  try {
    actual = readFileSync(TARGET, 'utf8')
  } catch {
    // A missing module is stale by definition; the comparison below reports it.
  }
  if (actual !== expected) {
    console.error('gen-distro-manifest: lyteboat/plugins/distro/src/distro-manifest.ts is stale; run node --import tsx scripts/dist/gen-distro-manifest.ts')
    process.exitCode = 1
  }
} else {
  writeFileSync(TARGET, expected)
}
